import{_ as o,o as a,c as i,ag as e}from"./chunks/framework.QfQ7DfGu.js";const m=JSON.parse('{"title":"龙架构开发指南","description":"","frontmatter":{"title":"龙架构开发指南","outline":"deep"},"headers":[],"relativePath":"misc/developer.md","filePath":"misc/developer.md"}'),n={name:"misc/developer.md"};function r(s,l,t,c,p,h){return a(),i("div",null,[...l[0]||(l[0]=[e('<h1 id="龙架构资源网站" tabindex="-1">龙架构资源网站 <a class="header-anchor" href="#龙架构资源网站" aria-label="Permalink to &quot;龙架构资源网站&quot;">​</a></h1><hr><div class="developer"><p>此处收集一些面向龙架构的软硬件资源网站，汇总如下：</p><section class="dlmi-card"><h2 id="龙芯开源社区" tabindex="-1">龙芯开源社区 <a class="header-anchor" href="#龙芯开源社区" aria-label="Permalink to &quot;龙芯开源社区&quot;">​</a></h2><div class="dlmi-actions"><a class="dlmi-chip dlmi-chip--link" href="https://www.loongnix.cn/zh/" target="_blank" rel="noopener noreferrer"><span class="dlmi-chip__text">点击跳转</span></a></div><p>龙芯开源社区是龙芯处理器的基础软件生态建设平台，包含有：</p><ul><li>Loongnix系统安装镜像、虚拟机镜像等下载。</li><li>龙芯浏览器。</li><li>提供 LoongArch 架构下最新 JDK。</li><li>提供 LoongArch 架构下最新 .net。</li><li>提供 LoongArch 架构下的 FFmpeg 与 X264。</li><li>Electron 框架支持。</li><li>以及其他基础软件、图形视频驱动、调试工具、应用工具等。</li></ul></section><section class="dlmi-card"><h2 id="龙芯应用合作社" tabindex="-1">龙芯应用合作社 <a class="header-anchor" href="#龙芯应用合作社" aria-label="Permalink to &quot;龙芯应用合作社&quot;">​</a></h2><div class="dlmi-actions"><a class="dlmi-chip dlmi-chip--link" href="https://app.loongapps.cn/home" target="_blank" rel="noopener noreferrer"><span class="dlmi-chip__text">点击跳转</span></a></div><p>龙芯应用合作社，提供龙架构下适配的系统软件，方便下载、安装和使用。</p></section><section class="dlmi-card"><h2 id="loongson生态创新中心" tabindex="-1">loongson生态创新中心 <a class="header-anchor" href="#loongson生态创新中心" aria-label="Permalink to &quot;loongson生态创新中心&quot;">​</a></h2><div class="dlmi-actions"><a class="dlmi-chip dlmi-chip--link" href="https://gitee.com/cn-loongson" target="_blank" rel="noopener noreferrer"><span class="dlmi-chip__text">点击跳转</span></a></div><p>龙芯生态创新衷心，包含有：</p><ul><li>helm LoongArch 源</li><li>MongoDB 支持 LoongArch 架构版</li><li>openstack 支持 LoongArch 架构版</li></ul><p>以及其他前沿创新应用。</p></section><section class="dlmi-card"><h2 id="龙架构漂流板-loongfly" tabindex="-1">龙架构漂流板(LoongFly) <a class="header-anchor" href="#龙架构漂流板-loongfly" aria-label="Permalink to &quot;龙架构漂流板(LoongFly)&quot;">​</a></h2><div class="dlmi-actions"><a class="dlmi-chip dlmi-chip--link" href="https://github.com/loongson-community/1024" target="_blank" rel="noopener noreferrer"><span class="dlmi-chip__text">点击跳转</span></a></div><p>龙芯1024计划旨在为开发者提供全面支持，通过项目和服务提升开发效率和应用性能，促进龙芯生态系统发展。旨在创建一个高效、友好的龙架构开发环境。</p><p>计划包括:</p><ul><li>开发环境支持</li><li>文档资源下载</li><li>社区论坛讨论</li></ul><p>开发者可获得最新技术信息、资源和专业支持，创造优秀作品。 计划还鼓励社区贡献新工具，不断优化开发环境。文档体系全面，覆盖各层次，提供示例代码和案例分析，定期更新以保持信息时效性。</p><p>龙架构漂流板(1024计划)活动由龙芯爱好者社区(<a href="mailto:support@loongfans.com" target="_blank" rel="noreferrer">support@loongfans.com</a>)运营, 计划初期项目缺少自动化流程包含大量人工操作, 如有纰漏欢迎指正。</p></section><section><h2 id="loongarch版千问客户端v2-3-2" tabindex="-1">LoongArch版千问客户端v2.3.2 <a class="header-anchor" href="#loongarch版千问客户端v2-3-2" aria-label="Permalink to &quot;LoongArch版千问客户端v2.3.2&quot;">​</a></h2><div class="dlmi-actions"><a class="dlmi-chip dlmi-chip--link" href="https://github.com/kota-rina3/hokeshi/releases/download/qwen-linux-2.3.2/com.qianwen.otohime_2.3.2-fix1_loong64.deb" target="_blank" rel="noopener noreferrer"><span class="dlmi-chip__text">点击下载</span></a></div><p>Linux版千问客户端，支持登录，支持上传/下载文件 注：需要登录才能使用完整功能</p></section><section><h2 id="liblol" tabindex="-1">libLoL <a class="header-anchor" href="#liblol" aria-label="Permalink to &quot;libLoL&quot;">​</a></h2><div class="dlmi-actions"><a class="dlmi-chip dlmi-chip--link" href="https://liblol.aosc.io/" target="_blank" rel="noopener noreferrer"><span class="dlmi-chip__text">点击下载</span></a></div><p>libLoL (LoongArch on LoongArch) 是一款用于提供旧世界 ABI 兼容性的运行时。 旧世界 ABI 常用于为龙芯提供的 Loongnix 参考发行版和统信 UOS 设计的商业软件，如腾讯 QQ Linux 版、金山 WPS for Linux 和龙芯浏览器等。由于这些应用程序尚未移植到新世界 ABI 上，本运行时旨在为新世界发行版用户提供运行上述应用程序的便利。</p></section></div>',3)])])}const g=o(n,[["render",r]]);export{m as __pageData,g as default};
